pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    let sign = if value.is_sign_negative() { "-" } else { "" };
    let abs = value.abs();

    if abs == 0.0_f32 {
        return format!("{sign}0");
    }

    // `std::cout` defaults to 6 significant digits and switches between fixed
    // and scientific notation using the rounded scientific exponent.
    let scientific = format!("{abs:.5e}");
    let (mantissa, exponent) = scientific
        .split_once('e')
        .expect("Rust scientific formatting should always include an exponent");
    let exponent = exponent
        .parse::<i32>()
        .expect("Rust scientific exponent should parse as i32");

    if (-4..6).contains(&exponent) {
        let fractional_digits = (5 - exponent) as usize;
        return format!("{sign}{}", trim_trailing_zeros(&format!("{abs:.fractional_digits$}")));
    }

    let exponent_sign = if exponent < 0 { '-' } else { '+' };
    let exponent_abs = exponent.abs();
    format!(
        "{sign}{}e{exponent_sign}{exponent_abs:02}",
        trim_trailing_zeros(mantissa)
    )
}

fn trim_trailing_zeros(text: &str) -> String {
    let trimmed = text.trim_end_matches('0').trim_end_matches('.');
    trimmed.to_string()
}

